package app.kivo.store;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public class RemoteApkTest {
 static void check(boolean yes,String why){if(!yes)throw new AssertionError(why);}
 static RemoteApk.Source bytes(byte[] value){return new RemoteApk.Source(){public long size(){return value.length;}public byte[] read(long at,int n){return Arrays.copyOfRange(value,(int)at,(int)at+n);}};}
 static void reject(RemoteApk.Source source)throws Exception{try{RemoteApk.inspect(source);throw new AssertionError("Malformed APK accepted");}catch(Exception expected){}}
 static byte[] zip(byte[] manifest,boolean stored)throws Exception{ByteArrayOutputStream buffer=new ByteArrayOutputStream();try(ZipOutputStream out=new ZipOutputStream(buffer)){ZipEntry entry=new ZipEntry("AndroidManifest.xml");if(stored){CRC32 crc=new CRC32();crc.update(manifest);entry.setMethod(ZipEntry.STORED);entry.setSize(manifest.length);entry.setCrc(crc.getValue());}out.putNextEntry(entry);out.write(manifest);out.closeEntry();}return buffer.toByteArray();}
 public static void main(String[] args)throws Exception{if(args.length<1)throw new IllegalArgumentException("Pass a Kivo APK path and expected versionCode");File f=new File(args[0]);long expected=args.length>1?Long.parseLong(args[1]):16;long[] read={0};RemoteApk.Source source=new RemoteApk.Source(){public long size(){return f.length();}public byte[] read(long off,int n)throws Exception{byte[] b=new byte[n];try(RandomAccessFile in=new RandomAccessFile(f,"r")){in.seek(off);in.readFully(b);}read[0]+=n;return b;}};RemoteApk.Identity id=RemoteApk.inspect(source);check(id.pkg.equals("app.kivo.store")&&id.code==expected&&id.minSdk==26,"Actual binary manifest identity");check(read[0]<2*1024*1024&&read[0]<f.length(),"No complete-APK download needed");byte[] manifest;try(ZipFile z=new ZipFile(f);InputStream in=z.getInputStream(z.getEntry("AndroidManifest.xml"))){manifest=in.readAllBytes();}
 for(boolean stored:new boolean[]{false,true}){RemoteApk.Identity parsed=RemoteApk.inspect(bytes(zip(manifest,stored)));check(parsed.pkg.equals(id.pkg)&&parsed.code==id.code,"Both stored and deflated manifests supported");}
 reject(bytes(new byte[100]));reject(new RemoteApk.Source(){public long size(){return 501L*1024*1024;}public byte[] read(long at,int n){throw new AssertionError("Oversized source must not be read");}});reject(new RemoteApk.Source(){public long size(){return f.length();}public byte[] read(long at,int n){return new byte[Math.max(0,n-1)];}});
 int[] calls={0};reject(new RemoteApk.Source(){public long size(){return f.length();}public byte[] read(long off,int n)throws Exception{byte[] b=source.read(off,n);if(++calls[0]==5&&b.length>0)b[0]^=1;return b;}});
 byte[] malformed=manifest.clone();Arrays.fill(malformed,4,8,(byte)0xff);try{RemoteApk.manifest(malformed);throw new AssertionError("Unbounded XML accepted");}catch(IOException expectedFailure){}
 check(RemoteApk.assetUrl("salvador9797/Kivo-Store","https://github.com/Salvador9797/kivo-store/releases/download/v1/app.apk")&&!RemoteApk.assetUrl("a/b","https://github.com/a/b-evil/releases/download/v1/app.apk"),"Canonical owner/repo case is accepted, different repo is rejected");check(!RemoteApk.allowed(new java.net.URL("http://github.com/a/b"))&&!RemoteApk.allowed(new java.net.URL("https://example.com/a.apk")),"No insecure or arbitrary redirect hosts");System.out.println("PASS: real APK identity, bounded partial reads, stored/deflated manifests, corrupt/truncated/oversized ZIPs, malformed XML and redirect allowlist.");}
}
